CREATE TABLE users(id BIGINT PRIMARY KEY,email VARCHAR(255) UNIQUE NOT NULL,name VARCHAR(255) NOT NULL,role VARCHAR(32) NOT NULL,password_hash TEXT NOT NULL,balance DECIMAL(18,2) NOT NULL DEFAULT 0,status VARCHAR(32) NOT NULL DEFAULT "active",created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products(id VARCHAR(64) PRIMARY KEY,category VARCHAR(64) NOT NULL,name VARCHAR(255) NOT NULL,price DECIMAL(18,2) NOT NULL DEFAULT 0,unit VARCHAR(32),description TEXT);
CREATE TABLE services(id BIGINT PRIMARY KEY,user_id BIGINT,product_id VARCHAR(64),status VARCHAR(32),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders(id BIGINT PRIMARY KEY,user_id BIGINT,product_id VARCHAR(64),amount DECIMAL(18,2),status VARCHAR(32),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE tickets(id BIGINT PRIMARY KEY,user_id BIGINT,subject VARCHAR(255),message TEXT,status VARCHAR(32),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE transactions(id BIGINT PRIMARY KEY,user_id BIGINT,type VARCHAR(32),amount DECIMAL(18,2),status VARCHAR(32),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);